-- Quests recorded as they were picked up, collected from SavedVariables with
-- tools/harvest-quests.lua. The script rewrites this file but keeps hand
-- edits: remove a wrong record, or add after/afterTitle/needs/item*/instead/leadsTo/class/profession/repeatable.
--
-- [questID] = { title, level, group, dungeon, zone, mapID, x, y, giver, fromItem, handIn, repeatable,
--               side, after, afterTitle, needs, itemZone, itemMapID, itemX, itemY, instead, leadsTo, class,
--               profession, seeded }
-- after = the quest that comes first; needs = free text for anything else it takes;
-- itemZone/itemMapID/itemX/itemY = where the item it needs lies, e.g. a book (ctrl-click in the list);
-- instead = the alternative quest, when only one of the two can be done;
-- leadsTo = the quest this one sends you to, when that one does not need it;
-- class = the one class that can take it, as the client's token ("DRUID");
-- profession = the profession it takes, as the skill list names it ("Tailoring").
-- seeded = true: only known from DungeonLevelGuide's list, not yet seen in play.
-- handIn = true: never taken, handed straight in to the giver, who is where it was recorded.
-- repeatable = true: can be handed in again and again.
